import { test, expect } from '@playwright/test';

test.describe('Web Tables CRUD Operations', () => {
  test('should add a new record to the table', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    await page.fill('input[id="firstName"]', 'John');
    await page.fill('input[id="lastName"]', 'Doe');
    await page.fill('input[id="userEmail"]', 'john.doe@example.com');
    await page.fill('input[id="age"]', '30');
    await page.fill('input[id="salary"]', '50000');
    await page.fill('input[id="department"]', 'Engineering');
    await page.click('button.btn.btn-primary:has-text("Submit")');
    await expect(page).toHaveURL(/.*webtables/);
    await expect(page.locator('table')).toContainText('John Doe');
  });

  test('should not submit the form with empty fields and stay on the same page', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    await page.click('button.btn.btn-primary:has-text("Submit")');
    await expect(page).toHaveURL(/.*webtables/);
    await expect(page.locator('table')).toBeVisible();
  });
});
